#!/bin/bash
set -e

# Fix: Collect Payment was taking 4-5s because the WhatsApp bill send
# (PDF generation + Meta media upload + message send) ran inline before
# returning to the front desk. Now uses Next.js's after() to return the
# payment confirmation immediately, finishing the WhatsApp send in the
# background afterward.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/payments"
echo "" | base64 -d > "app/(main)/payments/actions.js"
echo "Wrote app/(main)/payments/actions.js"

git add "app/(main)/payments/actions.js"
git commit -m "Fix: defer WhatsApp bill send past payment response using after() -- was adding 4-5s"
git push

echo "Done."
